INSERT INTO `mod_lore_codex_entry` (`ID`, `Kind`, `Zone`, `SortOrder`, `Faction`, `RequiredState`, `Title`, `Body`, `Sources`) VALUES
(1500, 0, 15, 0, 0, 0, 'Dustwallow Marsh', 'Dustwallow Marsh is a fog-bound swamp on the eastern coast of Kalimdor, its western hills dividing it from the Barrens and the sea washing its shores to the north and east. Raptors, spiders, crocolisks and murlocs prowl its reeds, and for ages the marsh belonged to its beasts and to the Stonemaul ogres. Then, after the Third War, Jaina Proudmoore brought the survivors of her expedition to this coast and raised the island city of Theramore, guarded by watchtowers along the road west. The peace has never been easy. Daelin Proudmoore fell at Theramore when his fleet came against the Horde, and some of his loyal marines have since deserted their posts. The Stonemaul ogres, driven from their southern village by black dragonkin, now hold Brackenwall Village for the Horde, and in the Wyrmbog to the south Onyxia, daughter of Deathwing, broods in her lair.', 'warcraft.wiki.gg/wiki/Dustwallow_Marsh (geography, founding after the Third War, Stonemaul, black dragonflight, Grimtotem expansion); quest 1285 reward text (deserters loyal to Admiral Daelin); durotar.json 1408 (the admiral died at Theramore); quest 11214 (Steamwheedle outpost Mudsprocket); quest 1170 (Onyxia, daughter of Deathwing); warcraft.wiki.gg/wiki/Dustwallow_Marsh (Stonemaul already in the marsh, recruited by the Mok''nathal)'),
(1501, 1, 15, 1, 0, 0, 'Theramore Isle', 'Theramore stands on a rocky isle off the coast, a walled city of stone founded by the humans, dwarves and high elves who followed Jaina Proudmoore to Kalimdor after the battle of Mount Hyjal. Her mage tower rises at its heart, Foothold Citadel to the east, and the docks reach out into Dustwallow Bay, where Kul Tiras marines come and go on their monthly pay. A cook gathers swamp recipes for his uncle''s restaurant in Stormwind, and the physicians of Alliance Trauma train their surgeons here. Just north of the gates lies the city''s graveyard.', 'warcraft.wiki.gg/wiki/Theramore_Isle (founded by Jaina''s expedition of humans, dwarves and high elves after Hyjal; walls; Jaina''s Tower; Foothold Citadel); quest 1282 (Foothold Citadel east of Lady Jaina''s tower); quest 1264 (Kul Tiras marines paid at the start of every month); quest 1260 (Morgan Stern gathering recipes for the Blue Recluse); quest 6625 (Alliance Trauma at Theramore); quest 11191 (Babs Fizzletorque relighting the lighthouse on the island east); quest 11152 (Hyal monument, graveyard north of the gates); DB spawns: Baldruc 4321 gryphon master, Babs 23892, VanHowzen 12939 in area 513'),
(1502, 1, 15, 2, 0, 0, 'Foothold Citadel', 'Foothold Citadel is the great stone barracks of Theramore, standing east of Lady Jaina''s tower with training grounds at its doors, where guards spar against dummies and drill under their combat masters. Commander Samaul, entirely loyal to his lady, commands her forces from within. On the top floor Captain Garran Vimes runs the city guard and its investigations, Adjutant Tesoran keeps the records of every soldier and every piece of equipment, and Clerk Lendry answers questions about the citizens. The guards here call themselves the finest Alliance soldiers in Kalimdor, sworn to uphold Alliance law so far from home.', 'quest 1282 (large barracks east of Lady Jaina''s tower; Vimes on top floor); quest 1302 (Clerk Lendry at Foothold Citadel); quest 1265 reward and 1264 (Samaul commands Jaina''s forces, loyal to Proudmoore); quest 1259 (Tesoran keeps personnel and equipment records); quest 1285 reward text (missing means traitor); npc_text 1793 (Vimes gossip); warcraft.wiki.gg/wiki/Theramore_Isle (training grounds at its doors); DB spawns: combat dummies 4952, practicing guards 4951, Combat Masters 4924/5090; WMOAreaTable: area 514 reachable as an indoor area'),
(1503, 1, 15, 3, 0, 0, 'Sentry Point', 'Sentry Point is the first of Theramore''s watchtowers on the road north out of the city, a stone tower with a handful of guards, a few chairs and a crate of stores, keeping watch over the marsh, the road and the Dreadmurk Shore beyond. Captain Wymor commands the post. Theramore has struggled to keep a presence in the marsh at all, and it is through watchtowers like this one, strung along the road, that the city keeps one.', 'quest 1265 (first tower outside of Theramore); quest 11136, 11137 (Wymor at Sentry Point; Defias survivors); quest 11136 reward text (assessing your abilities); npc_text 11264; stormwind.json 151911 (Missing King chain, mentioned in one line); wowhead.com/classic/npc=5086 (Captain Wymor present in classic, no quests); quest 1265 description (searchers sent to the first tower outside Theramore); quest 1286 description (Theramore keeps several defensive watchtowers in the marsh only with a struggle)'),
(1504, 1, 15, 4, 0, 0, 'Dreadmurk Shore', 'The Dreadmurk Shore runs north of Theramore''s walls, a coast of mud flats, reeds and offshore islets where Mirefin murlocs keep their camps, their oracles and coastrunners crowding the beaches. The hulking Mudrock turtles that crawl the sand are hunted by Theramore''s cooks for their tongues, the forked ones above all, which are said to have a flavor of their own. Fish school in the shallows, and the tide washes up wreckage among the reeds.', 'quest 11136 (Dreadmurk Shore north of Theramore''s walls, red bandanas, shipwreck); quest 11137 (leader on a large island); quest 1203 (Razorspine with a big sword, near the beach); quest 1204 (forked Mudrock tongues); quest 11138, 11139 (Renn McGill, SI:7 salvage diver; Defias divers); DB spawns area 518: Mirefin murlocs, Mudrock Spikeshell, Defias Rummager/Diver/Conjuror, Garn Mathers 23679, Razorspine 23841, Renn McGill 23569; DB spawns area 518: Mirefin Oracle/Coastrunner, Firefin Snapper and Oily Blackmouth schools, Waterlogged Wreckage 180685; mod-individual-progression zone_dustwallow_marsh.sql (deletes creatures 23589 and 23841); quest 11138 description (Renn went north to dive when he heard of the shipwreck)'),
(1505, 1, 15, 5, 0, 0, 'Alcaz Island', 'Alcaz Island lies off the northeastern coast, a lush, tropical isle ruled by the Strashaz naga. Sirens, myrmidons and great hydras guard its shores, and the Tidelord Rrurgaz commands them from behind barred gates. The naga are not alone. The criminal mastermind Doctor Weavil, sworn enemy of the seer Narain Soothfancy, has landed his flying machine here with a band of minions. The bloodkelp the naga gather is sought by those who practice divination.', 'warcraft.wiki.gg/wiki/Alcaz_Island (naga, Weavil and his flying machine, Rrurgaz); DB spawns area 2079: Strashaz naga and hydras, Tidelord Rrurgaz 16072, Doctor Weavil 15552, Flying Machine 15553, Firemane Drake 23969, Portcullis gameobjects; creature_text 15552 (No hello for your old friend, Narain; greatest criminal mastermind); quest 8620 (Weavil, Narain''s arch-enemy); quest 11142 description and reward text (survey from the air, rune circle, dragonkin); quest 8970 (bloodkelp from the Strashaz naga); warcraft.wiki.gg/wiki/Alcaz_Island (tropical vegetation like the Echo Isles); creature_template_movement 23969 (Firemane Drakes fly)'),
(1506, 1, 15, 6, 0, 0, 'Witch Hill', 'Witch Hill is a stretch of marsh northwest of Theramore, along the road before it turns west, and its name has never been a comfortable one. Darkfang spiders creep through its reeds, and herbs grow thick by the water. At its heart stands Swamplight Manor, a lonely house whose current master, the hermit called Swamp Eye Jarl, asks travelers to help with his cooking.', 'quest 11177 (Swamplight Manor in the Witch Hill area, northwest on the road out of Theramore; previous owners disappeared); quest 11225 (everyone who settled at Swamplight Manor went mad); quest 11180 reward text (spirits amount to everyone who ever lived on this land); quest 11181 (witchbane, shallow waters); DB spawns: Witch Light 23585 x99, Risen Husk/Spirit, Giant Marsh Frog in 502/497; creature_queststarter: 11225 from Draz''Zilb 4501; DB spawns area 502: Darkfang Venomspitter 4414, Liferoot, Goldthorn, Kingsblood; quest 1218 (Jarl''s frog legs); wowhead.com/classic/quest=1218 (classic Soothing Spices: Jarl''s cooking, no frogs)'),
(1507, 1, 15, 7, 0, 0, 'North Point Tower', 'North Point Tower is the second outpost on the road north from Theramore, a stone watchtower whose garrison guards the road where it runs on toward the Quagmire and the swamp''s interior. Since the deserters seized Lost Point it has been the most distant of the city''s watchtowers, and its soldiers serve as Theramore''s eyes over the northern marsh, from the raptor-haunted fens to the reeds of Bluefen.', 'quest 11143 (North Point, second outpost on the road; Darill an expert on the Grimtotems); npc_text 11245 (most distant outpost since deserters took Lost Point); quest 11144 (Blackhoof used to attack the tower); quest 11145, 11146 (Lukas, captured patrols, raptors); quest 9437 (Dawn Runner, cargo and Ithania held at North Point); creature_text 17119 (cargo at the top of the tower); DB: Balandar 17095 and Ithania 17119 faction 1604 (blood elf Horde); quest 11212 (road beyond North Point turns south into the Quagmire); quest 11146 (raptor patch to the northeast)'),
(1508, 1, 15, 8, 0, 8, 'Blackhoof Village', 'Blackhoof Village is a large new settlement of the Grimtotem clan, raised near Bluefen in the north of the marsh around a windmill. From here the most warlike of the tauren clans raid the road and the towers of Theramore, and they cage the human soldiers they capture. Judging by the size of its raiding parties, a substantial force is based here, led by Grimtotem elders who are said to take their orders from Thunder Bluff.', 'quest 11201 (large new Grimtotem settlement near Bluefen; orders from Thunder Bluff); quest 11144 (most warlike clan; base to attack the tower; battle plan reward text); quest 11145 (captives held in cages); quest 11147 (windmill in the center); quest 11148 and 11200 (armaments never used in battle; Mosarn''s make); DB spawns area 512: Grimtotem Breaker, Spirit-Shifter, Elder, Theramore Prisoner, Blackhoof Cage, Blackhoof Armaments; quest 11148 description (substantial force judging from raiding parties); warcraft.wiki.gg/wiki/Dustwallow_Marsh (patch 2.3.0 rework: Mudsprocket, new Theramore and Brackenwall quests, Grimtotem at Blackhoof Village and Direhorn Post, Tabetha''s Farm renamed)'),
(1509, 1, 15, 9, 0, 0, 'Darkmist Cavern', 'Darkmist Cavern was once a mine, cut into the hills northwest of Brackenwall Village, but the miners are long gone and the darkmist spiders have taken it for themselves. Silkspinners and recluses web its tunnels, and few outside the marsh would bother them at all, except that their parts are oddly prized. The blacksmith of Brackenwall uses the acid of their venom sacs to clean burned metal, and the hermit at Swamplight Manor insists that the juice of an unpopped darkmist eye is a fine drink, smooth and salty.', 'quest 1322 (spiders have taken over an old mine, the Darkmist Cavern, northwest of the village; acidic venom); quest 1206 (Darkmist eye juice, smooth and salty); DB spawns area 499: Darkmist Spider, Silkspinner, Recluse'),
(1510, 1, 15, 10, 0, 0, 'Brackenwall Village', 'Brackenwall Village is the Horde''s stronghold in Dustwallow Marsh, a rough camp of huts in the northwest where the Stonemaul ogres took refuge after black dragonkin burned them out of their southern home. Overlord Mok''Morokk rules it, though not all his ogres are content: the learned Draz''Zilb refuses to call it home, and old Tharg still mourns the wife the dragons killed. Orcs and trolls of the Horde work alongside them. Krog watches the humans for Orgrimmar, and the spymaster Nazeer Bloodpike sends agents against Theramore, whose own infiltrators spy on the village from the reeds to the east.', 'warcraft.wiki.gg/wiki/Dustwallow_Marsh (Brackenwall founded by Stonemaul, the Horde''s foothold); quest 1166, 1168 (old home burned; Tharg''s wife killed); npc_text 11567 (Draz''Zilb will never call it home); npc_text 1818 (Krog); quest 1201 (Nazeer; Theramore infiltrators east of Brackenwall); quest 9437 (Balandar''s complaint)'),
(1511, 1, 15, 11, 0, 0, 'Shady Rest Inn', 'Only a blackened chimney and scattered rubble remain of the Shady Rest Inn, on the road where Dustwallow meets the Barrens. James Hyal built it, one of those who came across the sea with Lady Proudmoore, dreaming of a fine stopping place for travelers, and for a while it prospered. Then Theramore lost control of the marsh roads, and James was too stubborn to retreat behind the city''s walls. The inn was burned to the ground, and his wife and son were killed. Investigators from Theramore and Brackenwall have both picked through the ashes.', 'quest 1282 reward text (opened an inn at the edge of the Barrens; lost control of the roads; too stubborn); quest 1302 (James went with Lady Proudmoore across the sea); quest 11123 (destruction of the Shady Rest and murder of his family); quest 11152 (wife and son); quest 11123/11124 reward text (Tarem''s reflective powder); DB: Inspector Tarem 23567, Black Shield 20992, Reethe''s badge 21042, hoofprints 187273 in area 403'),
(1512, 1, 15, 12, 0, 0, 'Lost Point', 'Lost Point is a Theramore watchtower that the garrison could no longer hold, standing southeast of the ruined Shady Rest Inn. Abandoned by its soldiers, it has been taken over by deserters from Theramore''s own ranks, men whose loyalty to Admiral Daelin Proudmoore outlived the admiral. Their lieutenant, Balos Jacken, keeps them hidden here among the stones and supply crates, and he has little patience for anyone the captains of Theramore send his way.', 'quest 1286 (abandoned tower at Lost Point, southeast of the inn; Balos Jacken); quest 1287 (Reethe thrown out for raiding Brackenwall''s supplies; too few to fight); quest 1285 reward text (deserters loyal to Admiral Daelin); npc_text 11245 (deserters have taken over Lost Point); DB spawns area 506: Theramore Deserter 5057, Deserter Lieutenant 23637, Balos Jacken 5089; quest 1286 reward text (Did Vimes send you?); DB spawns area 506: Food Crate 153470'),
(1513, 1, 15, 13, 0, 0, 'Tabetha''s Farm', 'In the heart of the Quagmire, beside the road south of North Point Tower, stands the small farm of Tabetha, a hermit mage who has trained generations of apprentices here and who is a good deal older than she looks. Both Theramore and Brackenwall know her, and she has kept the peace between them as well as anyone. Young mages of both sides make the long trip into the swamp to learn from her, and her cottage stands open to anyone whose errand is pressing enough.', 'quest 11212 (deep in the swamp, road beyond North Point turning into the Quagmire; kept the peace); quest 11213 (Nazeer sends someone); quest 11156 (trained generations of apprentices; Garion wounded); quest 11173, npc_text 11309, creature_text 23600/23601 (reagent quarrel); quest 11150 (Direhorn to the north); quest 11185 (Andello Porter, SI:7 agent at Tabetha''s Farm); quest 1947 (young mages sent to her); npc_text 3590 (your errand must mean much to draw you so deep into the marsh)'),
(1514, 1, 15, 14, 0, 8, 'Direhorn Post', 'Direhorn Post is a Grimtotem war camp just north of Tabetha''s Farm, easy to find for the totems its tauren raise to announce themselves. By night its warriors chant of their deeds against everyone who has tried to settle in the marsh, and by day they raid the farm, determined to drive Tabetha and her students out. The camp holds a stranger guest: a Forsaken apothecary named Cylla works among the Grimtotem destroyers and earthbinders.', 'quest 11150 (just north of my farm; totems announce their presence); quest 11156 (chanting about deeds against settlers; drive us from the farm); quest 11185 and 11186 (Apothecary Cylla''s letter, both factions); DB spawns area 4046: Grimtotem Destroyer, Earthbinder, Apothecary Cylla 23881, tents; DB spawns area 4046: Grimtotem Destroyer 23594, Earthbinder 23595; warcraft.wiki.gg/wiki/Dustwallow_Marsh (patch 2.3.0 rework: Mudsprocket, new Theramore and Brackenwall quests, Grimtotem at Blackhoof Village and Direhorn Post, Tabetha''s Farm renamed)'),
(1515, 1, 15, 15, 0, 0, 'Beezil''s Wreck', 'Beezil''s Wreck lies east of Tabetha''s Farm near the mountains, where a goblin zeppelin piloted by one Beezil came down in the swamp. The broken hull smolders in a heap of twisted metal and burning fuel, a scatter of crates lies about it, and acidic and bubbling oozes have gathered around the wreckage, while giant darkfang spiders haunt the ground nearby.', 'quest 11172 (crashed to the east of the farm, pilot Beezil, Steamwheedle representative); quest 11207 (six months'' worth of supplies for Mudsprocket); quest 11208 (Mudsprocket southwest, beyond the Stonemaul Ruins); npc_text 11403 (twisted metal and burning fuel); quest 11174 (oozes corroding the cargo); quest 1187 (seaforium booster lost when its zeppelin crashed in Dustwallow); DB: Zeppelin Cargo 186450 in areas 501 and 2302; quest 11172 reward text (How can I be sure that I can trust you?); DB spawns area 501: Acidic Swamp Ooze 4393, Bubbling Swamp Ooze 4394, Giant Darkfang Spider 4415, Gizmorium Shipping Crate, Damaged Crate'),
(1516, 1, 15, 16, 0, 0, 'Nat''s Landing', 'Across Dustwallow Bay to the southwest, in Tidefury Cove, a small island holds the fishing camp of Nat Pagle, one of the most famous fishermen in Azeroth. Nat''s Landing is little more than a small dock to fish from, which suits its owner. The cove around it is busy with Muckshell crab-men. Anglers who have learned all their own masters can teach come from both Orgrimmar and Ironforge, sent by their own trainers, to sit on this jetty and learn from him.', 'quest 11194 (small fishing camp on a little island in Tidefury Cove, southwest across Dustwallow Bay); quest 11209 (wrecked ship to the southwest; bait test); quest 6608 (Lumak sends Horde anglers), 6609 (from 5161 in Ironforge); quest 6607; DB spawns area 517: Muckshell Pincer/Scrabbler/Clacker, Lord Angler; warcraft.wiki.gg/wiki/Nat_Pagle (one of the most famous fishermen in all of Azeroth); warcraft.wiki.gg/wiki/Nat''s_Landing (small dock from which Nat fishes)'),
(1517, 1, 15, 17, 0, 0, 'Stonemaul Ruins', 'The Stonemaul Ruins were once the home of the Stonemaul ogres, a village in the south of the marsh with the clan''s great mound, now called the Den of Flame, cut into the hills nearby. Then the black dragonkin descended on it. They slew every Stonemaul who did not flee, and the survivors ran north to Brackenwall, leaving behind their dead and even their overlord''s grog, snuff and strongbox. Firemane dragonkin and searing whelps now hold the ruins.', 'quest 1170 (Stonemaul Village invaded by the brood of Onyxia); quest 11159 (dragonkin killed all Stonemaul who did not flee; spirits); quest 11160 (banner kept deep in the ogre mound, now called Den of Flame); quest 1166 (grog, snuff and strongbox in the Den of Flame and Stonemaul Ruins); creature_text 23786 (Where other Stonemauls?); DB spawns: Firemane Scout/Ash Tail, Searing Hatchling/Whelp, Ogre Remains 186332 in 508; Firemane in 509'),
(1518, 1, 15, 18, 0, 8, 'Mudsprocket', 'Mudsprocket is the Steamwheedle Cartel''s newest outpost, a muddy goblin town in the south of the marsh at the end of the road past Tabetha''s Farm and the Stonemaul Ruins. It welcomes Theramore and Horde traders alike and needs every contact it can get, for the zeppelin that should have stocked it crashed in the swamp, leaving it short of food, tools and medicine. Drazzit Dripvalve runs the town on a tight budget and has posted a bounty on Goreclaw the Ravenous, a raptor of the Bloodfen Burrow that has killed two of his engineers. Its oddest resident is Brogg, a Stonemaul ogre who lives in the only building big enough for him and plays dice with the goblins.', 'quest 11214 (Steamwheedle''s new outpost; Jaina wants trade contacts); quest 11215 (zeppelin crash left them without tools, food, medical supplies); quest 11184 (Goreclaw, Bloodfen Burrow, two engineers); quest 11184 reward text (budget); quest 11208 reward text (dice against the ogre); creature_text 23579 (only building that fits Brogg); warcraft.wiki.gg/wiki/Dustwallow_Marsh (Mudsprocket added in patch 2.3.0); warcraft.wiki.gg/wiki/Dustwallow_Marsh (patch 2.3.0 rework: Mudsprocket, new Theramore and Brackenwall quests, Grimtotem at Blackhoof Village and Direhorn Post, Tabetha''s Farm renamed)'),
(1519, 1, 15, 19, 0, 0, 'The Dragonmurk', 'The Dragonmurk is the steaming southern fen where the black dragonflight has made its home, and it takes its name from them. Onyxia''s brood has spread across it, and her eggs lie hidden among the reeds, each one another whelp to swell the dragonkin''s ranks. Firemane flamecallers and scalebanes stalk the mud, the black drake Brimgore prowls the fen, and Overlord Mok''Morokk''s lost strongbox lies somewhere in the muck. Bloodfen raptors and great crocolisks hunt here too, and veins of mithril and truesilver run through the hills.', 'warcraft.wiki.gg/wiki/Dustwallow_Marsh (black dragonflight gives Dragonmurk and Wyrmbog their names); quest 1172 (Onyxia''s brood scattered across the Dragonmurk; eggs); quest 11217 (wyrmtail, pulsates, abundant in the Dragonmurk and Wyrmbog); DB spawns area 510: Egg of Onyxia 20359, Firemane Scalebane/Flamecaller, Scorchscale Drake 23687, Brimgore 4339, Mok''Morokk''s Strongbox 19906; warcraft.wiki.gg/wiki/Brimgore (black drake); creature_template_movement 23687 (Scorchscale Drake flies); quest 1172 (Onyxia''s brood scattered across the Dragonmurk; eggs); DB spawns area 510: Bloodfen Lashtail/Razormaw, Drywallow Daggermaw, Mithril and Truesilver Deposits'),
(1520, 1, 15, 20, 0, 0, 'Wyrmbog', 'The Wyrmbog is the deepest corner of the south, a reeking marsh at the foot of the hills where the black dragonflight is strongest. Here, behind a cave mouth shaped like a dragon''s jaws, lies the lair of Onyxia, daughter of Deathwing and brood mother of the flight. Her eggs are hidden all around the entrance, guarded by firemane flamecallers, and great daggermaw crocolisks and darkfang spiders share the bog with them. In a den of its own nearby dwells the old drake Emberstrife.', 'quest 1172 (Wyrmbog, her lair, eggs); quest 11162 (cave like a dragon''s mouth; entrance to Onyxia''s Lair); quest 1170 (daughter of Deathwing); quest 6570 (Emberstrife''s den in the Wyrmbog); DB: Onyxia''s Gate 177928, Entrance to Onyxia''s Lair 186336 and eggs in area 511; DB spawns area 511: Drywallow Daggermaw, Giant Darkfang Spider'),
(1521, 2, 15, 1, 1, 0, 'Lady Jaina Proudmoore', 'Jaina Proudmoore, ruler of Theramore, is the daughter of Admiral Daelin Proudmoore of Kul Tiras and was once the apprentice of Archmage Antonidas of Dalaran. When the Scourge rose, a prophet urged her to lead survivors west across the sea, and in Kalimdor she stood with Thrall and the night elves against Archimonde at Mount Hyjal. Afterward she founded Theramore. When her father came with his fleet to make war on the Horde, she would not fight beside him, and he died at her city. She has worked for peace with the Horde ever since, though some marines loyal to her father have deserted rather than serve it. Her city, she says, must come first.', 'warcraft.wiki.gg/wiki/Jaina_Proudmoore (Kul Tiras, Antonidas, prophet, Hyjal, founded Theramore, Daelin''s assault); durotar.json 1408 (the admiral died at Theramore); quest 1285 reward text (deserters loyal to Admiral Daelin); npc_text 3157 (no time for pleasantries; my city must come first)'),
(1522, 2, 15, 2, 1, 0, 'Captain Garran Vimes', 'Captain Garran Vimes commands the Theramore guard from the top floor of Foothold Citadel, proud of his soldiers and of the Alliance law they keep so far from home. He reads Orcish better than most, which makes him the man to see when a Horde spy''s report turns up in the mud. Most of his days go to the mysteries of the marsh, chief among them the burning of the Shady Rest Inn, which his men have investigated with little luck. He has a soldier''s dry wit about the deserters, who accuse Theramore of betraying the Alliance while they betray it themselves, and a soft spot for poor James Hyal, the innkeeper who lost everything.', 'quest 1282 (top floor of Foothold Citadel; investigating); npc_text 1793; quest 1220 (knows the orcish language better than most); creature_text 4944 (spy report); quest 1285 reward text (delicious irony); quest 11123, 11152'),
(1523, 2, 15, 3, 1, 0, 'Smiling Jim', 'The man Theramore calls Smiling Jim stands in the city''s inn, grinning and singing the same few lines over and over, a song about a man who served mead and beer from ear to ear and year to year. His real name is James Hyal. He crossed the sea with Lady Proudmoore, a fine cook by his brother''s account, and built the Shady Rest Inn at the edge of the Barrens. When it was burned, his wife and son were killed, and James never recovered. The guards pity him and will not speak of it.', 'npc_text 1058 and creature_text 4895 (the song); quest 1282 (Guard Byron feels sorry for ol'' Jim; James Hyal his real name); quest 1302 (brother Vincent: went with Lady Proudmoore; damn fine cook); quest 11123 (James never recovered); creature_text 23768/23769 (Lynn and Jimmy Hyal at the monument); DB: Smiling Jim 4895 in area 513'),
(1524, 2, 15, 4, 2, 0, 'Overlord Mok''Morokk', 'Mok''Morokk rules the Stonemaul ogres at Brackenwall Village, raised to be their overlord by Rexxar himself. Under Rexxar''s eye he showed real strength, but once his patron left, power went to his head. When the black dragonkin burned the clan''s old home in the south, he ordered his people to run rather than fight, and he insists that the new village is safe because there are no dragons there. He calls himself a smart ogre and a good leader, but he pines most for his grog, his snuff and his strongbox, all abandoned in the flight. Many of his ogres want revenge and their old home. He would rather stay.', 'quest 1166 (Rexxar made me mighty leader; big dragons; grog, snuff, strongbox); quest 1171 reward text (strength when Rexxar led; fell to temptations of power); quest 1168 (told us to run); quest 1170 reward text (no dragons here); creature_text 4500 (Me still boss of ogres)'),
(1525, 2, 15, 5, 2, 0, 'Krog', 'Krog is an orc of Brackenwall Village and a shrewd agent of Orgrimmar. He boasts that the humans once claimed most of the marsh until the Stonemaul, with Horde help, pushed them back. Since the Shady Rest Inn burned he has taken a keen interest in whatever turns up in its ashes, for the Horde means to know what happened there. He has hunters like Kagoro and Ogron to track for him, knows a great many people across the Horde, and wears a set of armor the Earthen Ring gave him in thanks for some past service.', 'npc_text 1818 (humans claimed much of the marsh; Stonemaul pushed them back); quests 1251, 1268, 1269 (evidence from the inn brought to Krog); quest 1268 reward, creature_text 4926 (Kagoro); quest 1269 reward (Ogron); quest 1323 (Krog knows many people); quest 1276 (Earthen Ring armor by Mosarn); warcraft.wiki.gg/wiki/Krog (orc)'),
(1526, 2, 15, 6, 0, 0, 'Tabetha', 'Tabetha keeps a little farm in the heart of the Quagmire and is far more than the old hermit she seems. She is a mage and scryer of some renown, older than she looks, and she has trained apprentices here for generations, Horde mages among them. Young mages of both sides come to her to earn a mage''s wand, warlocks sent by Menara Voidrender bring her a tainted infernal orb whose demon she draws out, and she does not forgive theft: when the hydromancer Velratha of Zul''Farrak stole her Tiara of the Deep, she wanted it back badly. Both Theramore and Brackenwall trust her, and she has done more than most to keep the peace between them.', 'quest 11149 (mage and scryer of renown; seems little more than an old hermit); quest 11212 (older than she appears; kept the peace); quest 11156 (trained generations of apprentices); quest 11203 (trained some of our mages); quest 1947, 1948 (mage''s wand); quest 1799, 4961 (Menara''s orb); quest 2846 (Tiara of the Deep, Velratha); warcraft.wiki.gg/wiki/Tabetha'),
(1527, 2, 15, 7, 0, 8, 'Brogg', 'Brogg is a Stonemaul ogre who fled with Overlord Mok''Morokk when the black dragonkin took the clan''s old home, believing they would soon return to fight. The counterattack never came, and when his overlord refused to seek revenge for the friends Brogg had lost, he left Brackenwall for good. The goblins of Mudsprocket let him stay in the only building large enough to hold him, though he sometimes suspects they are laughing at him, and he trades the meat of his hunting trips at their dice table. He has never given up on his people. Brogg means to lay the Stonemaul dead to rest, avenge them, and lead the clan back where it belongs.', 'quest 11158 (left Brackenwall when the overlord would not take revenge); quest 11159 (fled with Mok''Morokk hoping for a counterattack that never came); npc_text 11281 (hears the goblins laughing); creature_text 23579 (only building that fits Brogg); quest 11208 reward text (dice against the ogre for what he killed hunting); quest 11162 reward text (never give up his quest to bring Stonemaul back); warcraft.wiki.gg/wiki/Dustwallow_Marsh (patch 2.3.0 rework: Mudsprocket, new Theramore and Brackenwall quests, Grimtotem at Blackhoof Village and Direhorn Post, Tabetha''s Farm renamed)'),
(1528, 2, 15, 8, 0, 0, 'Swamp Eye Jarl', 'The hermit called Swamp Eye Jarl lives alone at Swamplight Manor, and few who meet him think him quite right in the head. He loves swamp cooking above all things, fried frog legs and stews, and drinks the juice of spider eyes, talking fondly to the ones that stare back and saying they taste like chicken. He wants a particular swing blade for some cutting he will not explain, and he is in a hurry, for what he means to cut, he says, will not keep forever.', 'quest 1218 (frog legs, stew); quest 1206 reward text (spider eyes, taste like chicken); quest 1203 description (swing blade; what I''m cutting won''t keep forever)'),
(1529, 2, 15, 9, 0, 0, 'Nat Pagle', 'Nat Pagle is one of the most famous fishermen in Azeroth, though he claims he does not much enjoy fishing, having done it for twenty or thirty years. To him the best part is the slow pace, time to think about past and future, and a fine excuse to drink, heavily. Master anglers of both the Horde and the Alliance are sent to his island camp in Dustwallow when their own teachers have nothing left to give, and Nat tests them with lists of rare fish from far shores. He swears by a lucky measuring tape that he says helps him catch bigger fish.', 'quest 6607 (20 or 30 years; rare fish); npc_text 7638 (slow pace, excuse to drink); npc_text 7639 (lucky measuring tape); quest 6608, 6609 (anglers sent to Nat); quest 11209 (it''s all true; seen a few with my own eyes; new baits)'),
(1530, 2, 15, 10, 2, 0, 'Emberstrife', 'Emberstrife is an ancient drake of the black dragonflight who dwells in a den of his own in the Wyrmbog. He is an old gatekeeper of Nefarian, charged with testing the dragonspawn who would rise to the rank of elite guard to Onyxia, and he scorns most who come before him as mere whelps. In the name of Deathwing, whom he calls Father, he sets them the Test of Skulls: to slay the drake champions of the lesser flights, Scryer of the blue, Somnus of the green, Chronalis of the bronze and Axtroz of the red. Champions seeking the Seal of Ascension come instead to break his will and forge it in his flame.', 'quest 6570 (ancient drake; old gatekeeper of Nefarian; tests dragonspawn for elite guard to Onyxia); quest 6570 reward text (whelps); quests 6582-6585 (Scryer, Somnus, Chronalis, Axtroz; our Father); quest 6601 (medallion from the skulls; Guardian to the brood mother); quest 4743 (break his will to forge the Seal of Ascension); creature_text 10321 (will falters); quest 6570 reward text (sending me whelps)'),
(1531, 3, 15, 1, 1, 0, 'Ashes of the Shady Rest', 'The Shady Rest Inn lies in ashes at the edge of the Barrens, James Hyal''s wife and son are dead, and James himself sings in Theramore''s inn, lost to grief. Captain Garran Vimes of the Theramore guard has investigated with little luck, since the roads of the marsh slipped out of Theramore''s control, and he welcomes anyone willing to help. The rubble still holds things worth finding: rows of hoofprints leading away into the soft mud, a blackened iron shield fixed to the crumbling chimney, and, glinting under the debris, the Theramore badge of a Lieutenant Paval Reethe.', 'quests 1282, 1302, 1252, 1253, 1284, 1259, 1285, 1286, 1287, 1319, 1320 (Alliance investigation); quests 11123, 11143, 11144, 11148, 11149, 11150, 11151, 11152; creature_text 23768 (Lynn Hyal at the monument); quests 1252, 1253, 1284 descriptions (the clues); quest 1282 reward text (Vimes''s investigation, roads lost); warcraft.wiki.gg/wiki/Dustwallow_Marsh (patch 2.3.0 rework: Mudsprocket, new Theramore and Brackenwall quests, Grimtotem at Blackhoof Village and Direhorn Post, Tabetha''s Farm renamed); creature_text 23768 (Lynn Hyal at the grave)'),
(1532, 3, 15, 2, 2, 0, 'The Black Shield', 'The Shady Rest Inn has burned, and its owner''s woman and pup were killed with it. In Brackenwall Village, Krog wants to know who did it, and whatever turns up in the ashes is brought to him: rows of hoofprints in the mud, a Theramore badge bearing the name of one Paval Reethe, and a plain iron shield, blackened by the fire, fixed to what is left of the chimney. Krog guesses at quilboar or centaur from the Barrens and sends his trackers out, but he wants every lead run down.', 'quests 1251, 1268, 1269, 1273, 1321, 1322, 1323, 1276, 11204 (Horde investigation); creature_text 4980, 4983 (Reethe shot by an arrow); quests 11124, 11200, 11201, 11203, 11205, 11206; quest 11206 description and reward text (rein in the Grimtotems; report to the Warchief); quest 1251 reward text (a warning? a threat?); quest 1268 reward text (quilboar or centaur; woman and pup killed); warcraft.wiki.gg/wiki/Dustwallow_Marsh (patch 2.3.0 rework: Mudsprocket, new Theramore and Brackenwall quests, Grimtotem at Blackhoof Village and Direhorn Post, Tabetha''s Farm renamed)'),
(1533, 3, 15, 3, 1, 8, 'The Deserters', 'Not every soldier who followed the Proudmoores to Kalimdor followed Jaina''s peace. Deserters loyal to the late admiral have slipped agents back into Theramore, chatting up guards at every post and the docks, buying rounds, praising Admiral Proudmoore as the true hero and Lady Jaina as a coward, and hinting that friends of theirs know how to bring the old days back. Calia Hastings of SI:7 has come to Theramore to end it. She wants the agitators found, exposed and discredited, quietly, since anything more risks winning them sympathy.', 'quests 11126, 11128, 11133, 11134 (descriptions and reward texts); creature_text 23602 (agitator lines); creature_text 23566 (creative editing); creature_text 23941 (Gavis surrenders; spare my men); warcraft.wiki.gg/wiki/Theramore_Isle (Gavis Greyshield, former militia lieutenant, propaganda campaign); quest 11126 description; creature_text 23602 (buy a round; friends who know how to bring those days back); warcraft.wiki.gg/wiki/Dustwallow_Marsh (patch 2.3.0 rework: Mudsprocket, new Theramore and Brackenwall quests, Grimtotem at Blackhoof Village and Direhorn Post, Tabetha''s Farm renamed)'),
(1534, 3, 15, 4, 1, 8, 'Precious Cargo', 'Theramore''s scouts bring strange news: men wearing the red bandanas of the Defias walk the Dreadmurk Shore north of the city''s walls, and wreckage off the beach suggests they survived a shipwreck. The Defias are craftsmen and guildsmen, not sailors, and they have never shown any interest in Kalimdor. Captain Wymor at Sentry Point means to learn what they are doing here, and their leader, Garn Mathers, is rumored to hold a large island just off the coast to the northeast of the tower. Wymor has suspicions about these survivors, and wants help confirming them.', 'quests 11136, 11137, 11138, 11139, 11140, 11141, 11142 (descriptions and reward texts); creature_text 23569 (manacles: the cargo was a person); creature_text 4968 (Jaina''s explanation, used only for ''perhaps I should explain'' and ''fool to think them broken''); mod-individual-progression quest_missing_diplomat.sql (11142 reward text rewritten; 11222, 11223 rerouted); stormwind.json 151911 and 151914 (the abduction and Onyxia''s unmasking, not retold); warcraft.wiki.gg/wiki/Dustwallow_Marsh (patch 2.3.0 rework: Mudsprocket, new Theramore and Brackenwall quests, Grimtotem at Blackhoof Village and Direhorn Post, Tabetha''s Farm renamed)'),
(1535, 3, 15, 5, 1, 8, 'The Beast Beneath the Lighthouse', 'The old lighthouse on the island east of Theramore has been dark for some time, and the engineer Babs Fizzletorque has taken it into her head to relight it, sure that it will ease the passage of ships and goods into the docks. The sergeant on the docks cannot object, though she wonders how Babs means to manage it alone. The lighthouse''s own log holds the answer to the first problem: its lamp once burned oil from the young murk threshers that live right under Theramore''s docks.', 'quests 11191, 11192, 11193, 11194, 11209, 11210, 11198 (descriptions and reward texts); creature_text 23905 (marksmen; we defeated the sea monster); quest 11191 description (Babs means to relight it; smoother shipping; sergeant''s doubts); quest 11192 description (thresher oil from under the docks); warcraft.wiki.gg/wiki/Dustwallow_Marsh (patch 2.3.0 rework: Mudsprocket, new Theramore and Brackenwall quests, Grimtotem at Blackhoof Village and Direhorn Post, Tabetha''s Farm renamed)'),
(1536, 3, 15, 6, 2, 0, 'The Brood of Onyxia', 'The Stonemaul ogres fled their village in the south when black dragons fell upon it, and at first no one in Brackenwall could say whose dragons they were. Draz''Zilb, an ogre mage as learned as he is scornful of his overlord, means to find out by casting his spells over the hearts and tongues of the whelps that now infest the old village. Overlord Mok''Morokk will hear none of it: there are no dragons in Brackenwall. Tharg, who lost his wife in the attack, wants neither spells nor talk but revenge, and sends warriors against the black dragon army in the hope of going home.', 'quests 1169, 1170, 1171, 1172, 1173 (descriptions and reward texts); quest 1168 (Tharg''s wife; revenge); creature_text 4501 (The brood of Onyxia!); creature_text 4500 (Me scared! Me run now!); quest 1168 description (Tharg''s revenge); quest 1169 description (Draz''Zilb)'),
(1537, 3, 15, 7, 0, 8, 'Challenge to the Black Flight', 'Brogg has waited long enough for his overlord to avenge the Stonemaul, so from Mudsprocket he means to do it himself. He left Brackenwall when Mok''Morokk would not take revenge on the black dragonkin who destroyed the clan''s old home and killed many of Brogg''s friends, and he has come south to lay their spirits to rest and avenge them. First he needs feathers with strong magic for his ritual, like those the raptors of the Bloodfen Burrow wear, west of town.', 'quests 11158, 11160, 11161, 11159, 11162 (descriptions and reward texts); creature_text 23789 (Smolderwing); smart_scripts 23789/2378900 (Smolderwing flies to the Stonemaul Banner); quest 11158 description; warcraft.wiki.gg/wiki/Dustwallow_Marsh (patch 2.3.0 rework: Mudsprocket, new Theramore and Brackenwall quests, Grimtotem at Blackhoof Village and Direhorn Post, Tabetha''s Farm renamed)'),
(1538, 3, 15, 8, 2, 0, 'The Last Report of Marg Nighteye', 'The Horde and Theramore keep an uneasy truce in the marsh, and Nazeer Bloodpike, the spymaster of Brackenwall, means to come out on top of it. His hunters cull the Alliance infiltrators who watch the village, and his agents dive beneath the Theramore docks for documents thrown into the sea by spies caught aboard a ship. One of his agents, Marg Nighteye, was stationed outside Theramore for weeks to spy on the city, and his reports have stopped coming. Out in the swamp, loose dirt hides more than mud.', 'quests 1201, 1202 (uneasy truce; infiltrators; Captain''s Documents); quests 1238, 1239, 1240, 1261, 1262, 7541 (descriptions and reward texts); creature_text 4944 (Vimes on the same spy report, not used); quest 1238 description (weeks spying on Theramore)'),
(1539, 3, 15, 9, 0, 8, 'The Haunting of Witch Hill', 'Mordant Grimsby, an herbalist, came out to Swamplight Manor to visit his old friend Jarl with a housewarming gift, and found him babbling about frogs in an empty cabin while the dead walked outside. It has been a nonstop horror show ever since. Mordant will not leave his friend to it. He believes that the risen husks and spirits shambling about Witch Hill must know what happened here, and that if they can be laid to rest one by one, they may give up what they know before the evil consumes Jarl.', 'quests 11180, 11181, 11183 (descriptions and reward texts); creature_text 23843 (housewarming gift; babbling about frogs); creature_text 23864 (Zelfrax); warcraft.wiki.gg/wiki/Witch_Hill (haunted by the demon Zelfrax); quest 11180 description; creature_text 23843 (housewarming gift; babbling about frogs); warcraft.wiki.gg/wiki/Dustwallow_Marsh (patch 2.3.0 rework: Mudsprocket, new Theramore and Brackenwall quests, Grimtotem at Blackhoof Village and Direhorn Post, Tabetha''s Farm renamed)');
INSERT INTO `mod_lore_codex_part` (`Entry`, `Part`, `MinState`, `MaxState`, `Body`, `Sources`) VALUES
(1500, 1, 8, 255, 'The marsh has grown busier of late. Grimtotem tauren, the most warlike of their people, have pushed into the north and raised new camps of their own, and goblins of the Steamwheedle Cartel have founded Mudsprocket in the south, a trading town that welcomes Theramore and the Horde alike.', 'quest 11201 (Blackhoof Village a large new Grimtotem settlement); quest 11144 (most warlike of the tauren clans); quest 11214, 11215 (Steamwheedle''s new outpost, Theramore and Horde both sent); warcraft.wiki.gg/wiki/Dustwallow_Marsh (patch 2.3.0 rework: Mudsprocket, new Theramore and Brackenwall quests, Grimtotem at Blackhoof Village and Direhorn Post, Tabetha''s Farm renamed)'),
(1501, 1, 8, 255, 'Of late an engineer, Babs Fizzletorque, has set out to relight the old lighthouse on the island to the east, which has been dark for some time, sure that it will ease the passage of ships and goods into the docks. In the graveyard north of the gates stands the Hyal family monument, one of the larger stones there.', 'quest 11191 (lighthouse out to the east dark for some time; Babs means to get it working; smoother shipping); quest 11152 (Hyal monument, one of the larger stones in the graveyard north of the gates); DB: Hyal Family Monument gameobject 186322 (2.3 era id); warcraft.wiki.gg/wiki/Dustwallow_Marsh (patch 2.3.0 rework: Mudsprocket, new Theramore and Brackenwall quests, Grimtotem at Blackhoof Village and Direhorn Post, Tabetha''s Farm renamed)'),
(1503, 1, 8, 255, 'Wymor''s scouts have lately brought back the strangest report the garrison has heard in years: survivors of a shipwreck walking the Dreadmurk Shore, all of them wearing the red bandanas of the Defias. The captain makes no secret of sizing up every newcomer who offers to help him look into it.', 'quest 11136 description and reward text (Defias survivors; assessing your abilities); quest 11137 description; warcraft.wiki.gg/wiki/Dustwallow_Marsh (patch 2.3.0 rework: Mudsprocket, new Theramore and Brackenwall quests, Grimtotem at Blackhoof Village and Direhorn Post, Tabetha''s Farm renamed)'),
(1504, 1, 8, 255, 'Lately the shore has new tenants. A ship was wrecked off the coast, and its survivors, wearing Defias red, now camp on the islands under their leader Garn Mathers, sending divers and conjurors to search the sunken wreckage. An SI:7 salvage diver, Renn McGill, came north from Theramore when he heard of the wreck, and now dives in the same waters.', 'quest 11136 (Dreadmurk Shore north of Theramore''s walls, red bandanas, shipwreck); quest 11137 (leader on a large island); quest 11138, 11139 (Renn McGill, SI:7 salvage diver; Defias divers); DB spawns area 518: Defias Diver/Conjuror, Garn Mathers 23679, Renn McGill 23569; warcraft.wiki.gg/wiki/Dustwallow_Marsh (patch 2.3.0 rework: Mudsprocket, new Theramore and Brackenwall quests, Grimtotem at Blackhoof Village and Direhorn Post, Tabetha''s Farm renamed)'),
(1505, 1, 8, 255, 'Fire drakes of the black dragonflight now wheel above the island. When Theramore surveyed it from the air, the gryphon rider saw a rune circle and dragonkin at work there, a sign that the Defias wrecked off this coast were serving a far greater master than any of their own.', 'quest 11142 description and reward text (survey from the air, rune circle, dragonkin); DB: Firemane Drake 23969 over Alcaz (2.3 era creature, flies); creature_text 4968 lines 0-5 (said on completing 11142); warcraft.wiki.gg/wiki/Dustwallow_Marsh (patch 2.3.0 rework: Mudsprocket, new Theramore and Brackenwall quests, Grimtotem at Blackhoof Village and Direhorn Post, Tabetha''s Farm renamed)'),
(1506, 1, 8, 255, 'Pale witch lights drift over the water now, and the dead walk the hill, risen husks and spirits. The manor''s owners vanished under mysterious circumstances, and everyone who has settled there since has gone mad, or so Draz''Zilb of Brackenwall says. In the shallows grows witchbane, an herb whose smoke, hedge mages claim, can draw evil from its hiding place. Around the manor itself giant marsh frogs have overrun the grounds, which suits Jarl and his frying pan well enough.', 'quest 11177 (previous owners disappeared); quest 11225 (everyone who settled at Swamplight Manor went mad); quest 11181 (witchbane, shallow waters); DB spawns: Witch Light 23585 x99, Risen Husk 23555, Risen Spirit 23554, Witchbane 186423 in 502/497 (2.3 era ids); warcraft.wiki.gg/wiki/Dustwallow_Marsh (patch 2.3.0 rework: Mudsprocket, new Theramore and Brackenwall quests, Grimtotem at Blackhoof Village and Direhorn Post, Tabetha''s Farm renamed)'),
(1507, 1, 8, 255, 'Captain Darill, something of an expert on the Grimtotem tauren, holds the tower against their raids from Blackhoof Village, while Sergeant Lukas tries to free the patrols they capture and dreams of turning the Bloodfen raptors loose on the tauren camp. The tower holds a prisoner of its own. When a blood elf ship called the Dawn Runner ran aground, Theramore''s men seized its cargo and its last surviving crewman, Ithania, and keep both at the top of the tower.', 'quest 11143 (Darill something of an expert on the Grimtotems); quest 11144 (Blackhoof used to attack the tower); quest 11145, 11146 (Lukas, captured patrols, raptors); quest 9437 (Dawn Runner, cargo and Ithania held at North Point); creature_text 17119 (cargo at the top of the tower); warcraft.wiki.gg/wiki/Dustwallow_Marsh (patch 2.3.0 rework: Mudsprocket, new Theramore and Brackenwall quests, Grimtotem at Blackhoof Village and Direhorn Post, Tabetha''s Farm renamed); Balandar 17095 and Ithania 17119: patch 2.0.1 blood elf additions, not phased by mod-individual-progression'),
(1508, 1, 0, 255, 'The elders'' battle plans, once taken and pieced together, leave no doubt about the clan''s aims: the Grimtotem of Blackhoof are moving against the humans who have settled in the marsh. The raids on the road and the towers are no mere banditry, but a war planned by the clan''s elders.', 'quest 11144 reward text (fight back against human settlements); quest 11201 reward text (moving against the humans)'),
(1508, 2, 0, 255, 'The arms stored at Blackhoof tell a story of their own: none of them has ever been carried into a real fight, only into drill. Whoever burned the Shady Rest Inn did not carry these, and the band responsible is still at large somewhere else in the marsh.', 'quest 11148 reward text (match exactly; never used in battle; not the only Grimtotem post); quest 11203 description (arms not seen combat beyond training; the Grimtotem who destroyed the Shady Rest still at large)'),
(1510, 1, 8, 255, 'A stranger has lately washed up among the ogres: the blood elf Balandar Brightstar, whose ship the Dawn Runner ran aground on the coast. He finds his hosts good for little but crude jokes, sour ale and bouts of headbutting, and wants his cargo and his crewman back from Theramore.', 'quest 9437 description (Balandar''s complaint; Dawn Runner aground; cargo and crewman taken); DB: Balandar Brightstar 17095 (patch 2.0.1, faction 1604)'),
(1511, 1, 8, 255, 'Theramore''s best investigator, Inspector Tarem, now works the ruins himself. He dusts them with a reflective powder that makes hidden clues and markings shine, and he has been told, to his visible distrust, that the Horde will aid his inquiry too.', 'quest 11123 description and reward text (Tarem, best investigator; reflective powder); quest 11124 reward text (Tarem''s distrust of the Horde''s aid); DB: Inspector Tarem 23567 in area 403; warcraft.wiki.gg/wiki/Dustwallow_Marsh (patch 2.3.0 rework: Mudsprocket, new Theramore and Brackenwall quests, Grimtotem at Blackhoof Village and Direhorn Post, Tabetha''s Farm renamed)'),
(1512, 1, 0, 255, 'Pressed about one of his former men, Balos admits the deserters cast out Paval Reethe, once a lieutenant, for raiding the supplies of the Brackenwall ogres once too often. They are too few to stand against the ogres and want no trouble with them, and Balos asks only to be forgotten.', 'quest 1287 description (Reethe thrown out for raiding Brackenwall''s supplies; too few to stand up to them; forget you bumped into us)'),
(1513, 1, 8, 255, 'Her two current students, Morlann and Garion, bicker endlessly over missing reagents, and Garion nurses a wound from the last Grimtotem raid. She has new neighbors, the Grimtotem of Direhorn Post just to the north, and when she fell out of touch both Theramore and Brackenwall sent people to check on her. An SI:7 agent, Andello Porter, has taken up quiet watch at the farm.', 'quest 11156 (generations of apprentices; Garion wounded); quest 11173, npc_text 11309, creature_text 23600/23601 (reagent quarrel); quest 11150 (Direhorn to the north); quests 11212, 11213 (out of touch; Theramore and Nazeer send someone); quest 11185 (Andello Porter, SI:7 agent at Tabetha''s Farm); warcraft.wiki.gg/wiki/Dustwallow_Marsh (patch 2.3.0 rework: Mudsprocket, new Theramore and Brackenwall quests, Grimtotem at Blackhoof Village and Direhorn Post, Tabetha''s Farm renamed)'),
(1514, 1, 0, 255, 'A letter carried by Apothecary Cylla tells why she is here. It comes from the new masters of Lordaeron, who have sent her as a token of good faith to aid the Grimtotem against their mutual enemy in Kalimdor, and it promises that none will stand before their combined might.', 'quest 11185 and 11186 descriptions (the letter, started from the item she carries)'),
(1514, 2, 0, 255, 'This was the camp of the band that burned the Shady Rest Inn. Tabetha needed no scrying to find it, and once she knew, she saw no reason to tolerate it: its tents were put to the torch from her farm, a message the Grimtotem could not mistake.', 'quest 11150 and 11205 descriptions and reward texts'),
(1515, 1, 8, 255, 'The zeppelin was carrying six months of supplies for the new goblin town at Mudsprocket, and what survived the crash is strewn across the marsh as far as the Quagmire. The Steamwheedle Cartel has sent Moxie Steelgrille, a wary goblin slow to trust strangers, to salvage what she can, but the oozes are slowly digesting the cargo before she can reach it.', 'quest 11207 (six months'' worth of supplies for Mudsprocket); quest 11208 (Mudsprocket southwest, beyond the Stonemaul Ruins); quest 11174 (oozes corroding the cargo); quest 11172 reward text (How can I be sure that I can trust you?); DB: Zeppelin Cargo 186450 in areas 501 and 2302; warcraft.wiki.gg/wiki/Dustwallow_Marsh (patch 2.3.0 rework: Mudsprocket, new Theramore and Brackenwall quests, Grimtotem at Blackhoof Village and Direhorn Post, Tabetha''s Farm renamed)'),
(1516, 1, 8, 255, 'A wrecked ship lies in the water to the southwest of the landing, and Nat sends the brave or the foolish swimming out to it, smeared in his foul-smelling newest baits, to see what bites.', 'quest 11209 (wrecked ship to the southwest; bait test); warcraft.wiki.gg/wiki/Dustwallow_Marsh (patch 2.3.0 rework: Mudsprocket, new Theramore and Brackenwall quests, Grimtotem at Blackhoof Village and Direhorn Post, Tabetha''s Farm renamed)'),
(1517, 1, 8, 255, 'Ogre bones still lie where they fell. The clan banner was left behind too, deep in the old mound, and the angry spirits of the Stonemaul dead are bound to their bones, rising when called and asking where the rest of their people have gone.', 'quest 11160 (banner kept deep in the ogre mound, now called Den of Flame); quest 11159 (spirits of the Stonemaul dead); creature_text 23786 (Where other Stonemauls?); DB: Ogre Remains 186332 (2.3 era gameobject); warcraft.wiki.gg/wiki/Dustwallow_Marsh (patch 2.3.0 rework: Mudsprocket, new Theramore and Brackenwall quests, Grimtotem at Blackhoof Village and Direhorn Post, Tabetha''s Farm renamed)'),
(1519, 1, 8, 255, 'A scorchscale drake now circles overhead. Not everything here is deadly, though: wyrmtail, a coiled herb that seems to pulse when looked at, grows thick in the Dragonmurk, and the goblins of Mudsprocket use it to dull pain and close wounds.', 'quest 11217 (wyrmtail, pulsates, abundant in the Dragonmurk and Wyrmbog); DB: Scorchscale Drake 23687, Wyrmtail 186463 (2.3 era ids); warcraft.wiki.gg/wiki/Dustwallow_Marsh (patch 2.3.0 rework: Mudsprocket, new Theramore and Brackenwall quests, Grimtotem at Blackhoof Village and Direhorn Post, Tabetha''s Farm renamed)'),
(1520, 1, 8, 255, 'Scorchscale drakes now guard the lair''s approach alongside the dragonkin, and wyrmtail, a coiled herb that seems to pulse when looked at, grows thicker in the Wyrmbog than anywhere else in the marsh.', 'DB: Scorchscale Drake 23687 (2.3 era id); DB: Wyrmtail 186463, 55 nodes in area 511; quest 11217 (wyrmtail abundant in the Dragonmurk and Wyrmbog); warcraft.wiki.gg/wiki/Dustwallow_Marsh (patch 2.3.0 rework: Mudsprocket, new Theramore and Brackenwall quests, Grimtotem at Blackhoof Village and Direhorn Post, Tabetha''s Farm renamed)'),
(1523, 1, 8, 255, 'At the Hyal family monument outside the gates, the spirits of his wife and little Jimmy linger. When word reached them that their murderers had been brought to justice, his wife gave thanks and asked that James be told they love him and are waiting for him. Captain Vimes promised to carry the message, though he doubts James will understand.', 'quest 11152 description and reward text; creature_text 23768/23769 (Lynn and Jimmy Hyal at the monument); warcraft.wiki.gg/wiki/Dustwallow_Marsh (patch 2.3.0 rework: Mudsprocket, new Theramore and Brackenwall quests, Grimtotem at Blackhoof Village and Direhorn Post, Tabetha''s Farm renamed)'),
(1524, 1, 0, 255, 'When at last he was challenged before his people, the overlord boasted that he would crush the upstart, was beaten, and ran wailing that he was scared. Even so he soon sat back among his ogres, still claiming to be their boss.', 'quest 1173 description and reward text (fled like a scared child); creature_text 4500 (Me crush; Me scared! Me run now!; Me still boss of ogres)'),
(1525, 1, 8, 255, 'Since Theramore sent its own inspector to the ruins, Krog has orders from Orgrimmar to assist him. He does it his own way: take whatever the human offers, feed him a tidbit or two, and save the real findings for the Horde.', 'quest 11124 description (orders from Orgrimmar to assist; save your real findings); warcraft.wiki.gg/wiki/Dustwallow_Marsh (patch 2.3.0 rework: Mudsprocket, new Theramore and Brackenwall quests, Grimtotem at Blackhoof Village and Direhorn Post, Tabetha''s Farm renamed)'),
(1528, 1, 8, 255, 'He took over the manor after its previous owners vanished, and he tells visitors to get off his lawn unless they mean to help in the kitchen. A sergeant at the Theramore docks sends people to check on him now and then, because he reminds her of her grandfather.', 'quest 11177 description and reward text (took over Swamplight Manor; reminds me of my grandfather; get off my lawn); warcraft.wiki.gg/wiki/Dustwallow_Marsh (patch 2.3.0 rework: Mudsprocket, new Theramore and Brackenwall quests, Grimtotem at Blackhoof Village and Direhorn Post, Tabetha''s Farm renamed)'),
(1529, 1, 8, 255, 'He is working on a new line of foul-smelling baits, and he swears the sailors'' tales of sea monsters are all true, having seen a few with his own eyes.', 'quest 11209 (it''s all true; seen a few with my own eyes; new line of baits); warcraft.wiki.gg/wiki/Dustwallow_Marsh (patch 2.3.0 rework: Mudsprocket, new Theramore and Brackenwall quests, Grimtotem at Blackhoof Village and Direhorn Post, Tabetha''s Farm renamed)'),
(1530, 1, 0, 255, 'When the last skull is laid before him, Emberstrife admits he had doubted the whelp''s dedication. From the skulls of the lesser flights he shapes a medallion, the badge worn by those who rise to Guardian of the brood mother, and sends its bearer back to the Spire for General Drakkisath''s final enchantment.', 'quest 6585 reward text (had doubted your dedication; prepare the skulls); quest 6601 description (medallion from the skulls; Guardian to the brood mother; to Drakkisath)'),
(1531, 1, 0, 255, 'Adjutant Tesoran''s books named Reethe a Kul Tiran marine who came across the sea with Lady Proudmoore, now listed as missing: the adjutant''s kind word, said Vimes, for traitor, one more deserter blindly loyal to the late admiral. The deserters at Lost Point admitted they had cast Reethe out for raiding the Brackenwall ogres'' supplies, and Vimes sent Lieutenant Caldwell to deal with them and to find him.', 'quest 1285 description and reward text; quest 1287 description and reward text'),
(1531, 2, 0, 255, 'The shield was no work of any smith on this side of the sea, said Caz Twosprocket at the Theramore forge, and its burned strap had been made for someone large, likely a tauren. It was little to go on, Vimes admitted, but it would have to be kept in mind.', 'quest 1319 reward text; quest 1320 description and reward text'),
(1531, 3, 8, 255, 'Inspector Tarem was certain the hoofprints and the shield pointed to the Grimtotem clan, and Vimes sent the searcher to Captain Darill at North Point, who knows the tribe well. From the new Grimtotem camp at Blackhoof Village came a battle plan that left no doubt: the clan meant to fight the human settlements of the marsh, and Theramore was surely next.', 'quest 11143 description and reward text; quest 11144 description and reward text'),
(1531, 4, 8, 255, 'Blackhoof''s arms matched those found at the inn exactly, but none had ever been used in battle. Blackhoof could not be the only Grimtotem post in the marsh, and the band that burned the inn was still out there somewhere.', 'quest 11148 reward text'),
(1531, 5, 8, 255, 'Tabetha had no need of her scrying, for the guilty band was camped right beside her farm at Direhorn Post, and its tents went up in flames. At the Hyal family grave the spirits of James''s wife and their little boy were waiting. His wife knew the one who had hunted down the brutes, gave her thanks, and sent James word of their love.', 'quests 11149, 11150, 11151, 11152 descriptions and reward texts; creature_text 23768 (Lynn Hyal at the monument)'),
(1532, 1, 8, 255, 'Of late Orgrimmar has its own stake in the matter. It has ordered Krog to assist Theramore''s investigator at the ruins while keeping the real findings for the Horde, for the Alliance must never be allowed to think the Horde had a hand in the burning.', 'quest 11124 description; quest 11203 description (the Alliance must not think we were complicit); warcraft.wiki.gg/wiki/Dustwallow_Marsh (patch 2.3.0 rework: Mudsprocket, new Theramore and Brackenwall quests, Grimtotem at Blackhoof Village and Direhorn Post, Tabetha''s Farm renamed)'),
(1532, 2, 0, 255, 'Krog knew Reethe as a deserter hiding in the swamp, suspected of stealing Brackenwall''s supplies. Ogron tracked him to an island, but before Reethe could tell what he knew, an arrow from the reeds struck him down. He was too frail, Krog grumbled, to survive a little arrow wound, and that thread of the mystery led nowhere.', 'quest 1269 reward text; quest 1273 description and reward text; creature_text 4980, 4983 (Reethe shot by an arrow)'),
(1532, 3, 0, 255, 'The shield fared better. Acid from darkmist spider venom cleaned its rim enough to show the name Mosarn, and Krog, who knows many people, at last remembered him: a well-respected blacksmith of Thunder Bluff. Mosarn knew the shield as his own work, but he makes so many that he could tell nothing more of it.', 'quests 1321, 1322, 1323 descriptions and reward texts; quest 1276 description and reward text'),
(1532, 4, 8, 255, 'Mosarn let slip one thing more: the Grimtotem are especially fond of his work, among his best customers. Krog seized on it. Mosarn had given more help than he knew, and with the hoofprints and the shield pointing the same way, the Grimtotem were the Horde''s first suspects.', 'quest 11204 description and reward text'),
(1532, 5, 8, 255, 'The battle plans of Blackhoof''s elders showed the Grimtotem moving against the humans, but the camp''s arms had never seen battle beyond training, so the raiders who burned the inn were still at large. Tabetha, who has trained Horde mages, pointed to their camp at Direhorn Post beside her farm. Its tents were burned, and she warned that the Horde can no longer afford to leave the Grimtotem unchecked. Krog carried it all to the Warchief, and asked for silence until Thrall has dealt with them.', 'quests 11200, 11201, 11203, 11205, 11206 descriptions and reward texts'),
(1533, 1, 0, 255, 'The agitators were confronted and driven off, caught off guard within walls they thought safe. Calia knew they would return, and their leaflets had come in aboard a privateer ship at the farthest dock. The rest were seized from its captain''s quarters, and Calia had just the plan for them.', 'quest 11126 reward text; quest 11128 description and reward text'),
(1533, 2, 0, 255, 'Calia altered the leaflets with a little creative editing, and when the pages went round the barracks, the guards laughed so hard that no deserter agent could ever again be taken seriously within the walls. Last came their base, a ship moored on an island southeast of the docks. Their leader, Gavis Greyshield, put up a show of a fight, then surrendered and asked only that his men be spared. With the proper handling, Calia believes, Lady Jaina could bring them back to the fold.', 'quests 11133, 11134 descriptions and reward texts; creature_text 23566 (creative editing); creature_text 23941 (Gavis surrenders; spare my men)'),
(1534, 1, 0, 255, 'Garn Mathers was slain and his orders brought back. They spoke of precious cargo, in words that hinted at a wealthy or noble patron, and the band''s first task was to recover it. Whatever it was, the Defias wanted it badly.', 'quest 11137 description and reward text'),
(1534, 2, 0, 255, 'With diving gear borrowed from the Defias and patched up by the SI:7 salvage diver Renn McGill, strongboxes were raised from the wreckage strewn toward Alcaz Island. Among old coins, ugly jewelry and letters home lay a pair of enchanted manacles. The cargo had not been a thing at all, but a person.', 'quests 11139, 11140 descriptions and reward texts; creature_text 23569 (manacles: the cargo was a person); quest 11141 description (prisoner of importance)'),
(1534, 3, 0, 255, 'Lady Jaina had Alcaz Island surveyed by gryphon, and the rider saw a rune circle and dragonkin at work. Jaina knew what that meant, and she explained the rest herself, privately. Whoever their captive had been, the Defias had sold themselves to a power far greater than any grudge of their own, and she admitted she had been a fool to think the Brotherhood broken.', 'quest 11142 description and reward text; creature_text 4968 lines 0 and 5 (Perhaps I should explain; fool to think them broken)'),
(1535, 1, 0, 255, 'With the lamp lit, Babs found an old book of sailors'' tales in a trunk upstairs, Dastardly Denizens of the Deep, good only for a laugh. The fishmonger Dirty Michael Crowe, who collects old books, did not laugh. Sailors still spoke, he said, of Tethyr, a sea creature the book says lives right here, and old Nat Pagle would know the truth of it.', 'quest 11193 description and reward text; quest 11194 description'),
(1535, 2, 0, 255, 'Nat would talk only after testing a foul new bait on the visitor who asked. Then he told it plain. Tethyr was real, he lived in the waters off Theramore, he was drawn to bright light, and he was the reason the lighthouse had been shut down in the first place. Light it again, and he would come back.', 'quest 11209 description and reward text; quest 11210 description'),
(1535, 3, 0, 255, 'Major Mills would not risk Theramore''s shipping. He mounted three mortars on the docks, lined up his best marksmen and ordered the lamp lit, and when the beast came the defenders held together and brought it down.', 'quest 11198 description and reward text; creature_text 23905 (marksmen; we defeated the sea monster)'),
(1536, 1, 0, 255, 'Draz''Zilb''s spells gave the answer: the brood of Onyxia, daughter of Deathwing. He doubted she had come to the marsh merely to besiege a band of ogres, and sent word to the overlord at once.', 'quest 1169 reward text; quest 1170 description; creature_text 4501 (The brood of Onyxia!)'),
(1536, 2, 0, 255, 'Mok''Morokk shrugged it off, since there were no dragons where he sat. Draz''Zilb sent others to the Wyrmbog instead to smash Onyxia''s eggs before more could hatch. When that was done, he asked one last service. Mok''Morokk was not fit to lead, and the old warrior Tharg was too hurt and too old, so the overlord had to be driven out by force.', 'quests 1170, 1171 reward texts; quest 1172 description and reward text'),
(1536, 3, 0, 255, 'Mok''Morokk was challenged before his people, beaten, and fled like a frightened child. The clan was free at last to choose a leader who would take them home to the south.', 'quest 1173 reward text; creature_text 4500 (Me scared! Me run now!)'),
(1537, 1, 0, 255, 'Brogg''s ritual needed more than feathers. The clan banner was brought out from deep in the old mound the dragonkin now call the Den of Flame, and the essences of the dragonkin who had killed his friends were gathered to feed his totem with their hate. At the Stonemaul Ruins the totem drew the restless ogre spirits from their bones so that they could be fought and laid to rest. The survivors could finally turn to the living, Brogg said, though Mok''Morokk would never give thanks. One task remained.', 'quest 11159 description and reward text; quests 11160, 11161 descriptions (banner or essences, either one leads to 11159)'),
(1537, 2, 0, 255, 'Brogg''s banner was carried east to the dragon''s-mouth cave of the Wyrmbog and planted before Onyxia''s lair as his challenge. The brood mother did not come. Her servant Smolderwing answered in her place, that Onyxia answers to no one, and Brogg decided that, like all her flight, she fights only when victory is certain. He will never give up on bringing the Stonemaul home.', 'quest 11162 description and reward text; creature_text 23789 (Smolderwing); smart_scripts 23789/2378900 (Smolderwing flies to the Stonemaul Banner)'),
(1538, 1, 0, 255, 'From the dirt came an orc''s severed hand, still clutching a bone tube with Marg''s last report. Nazeer feared his agent had met his end in the swamp. Soon after came his head, its ragged wound a mystery: a weapon, or some beast? Nazeer had to know whether the Alliance had killed him, and only troll witch-magic could tell.', 'quest 1238 description and reward text; quest 1239 reward text; quest 1240 description'),
(1538, 2, 0, 255, 'Kin''weelay of Grom''gol, the most powerful witchdoctor of the Darkspear, called up Marg''s furious spirit, which told the tale. On the beach near Theramore he had robbed a camp of soldiers of a pendant laden with more gems than any soldier could afford, and on his way home a muckshell crab-man had killed him.', 'quest 1240 reward text; quest 1261 description (the spirit''s words)'),
(1538, 3, 0, 255, 'The pendant was recovered from the muckshell. It was a noble''s jewel, far richer than a common soldier''s, and that was a new mystery. It went to Zor Lonetree in Orgrimmar, who knows Alliance politics, to be studied, in the hope that its mysteries would in time be revealed.', 'quest 1261 reward text; quest 1262 description and reward text; quest 7541 reward text (auto-complete, so QUEST_DONE)'),
(1539, 1, 0, 255, 'The dead told him this was no ordinary haunting. They were every soul who had ever lived on the land, not just the last owners, corrupted and killed by the same evil, each learning the truth too late.', 'quest 11180 reward text'),
(1539, 2, 0, 255, 'Mordant remembered that hedge mages use the smoke of witchbane to draw evil out of hiding. A torch bound with the herb was planted at the end of the manor''s dock, and from the smoke rose Zelfrax, who claimed the land as his long before mortals came. When he fell, Mordant was almost more surprised than relieved. Jarl''s taste in furniture, he admitted, remained beyond saving.', 'quests 11181, 11183 descriptions and reward texts; creature_text 23864 (Zelfrax); warcraft.wiki.gg/wiki/Witch_Hill (haunted by the demon Zelfrax)');
